//go:build bdd

// Code generated by `true-bdd build tests`. DO NOT EDIT.

package mcp_test

import (
	"os"
	"testing"

	"fixture/buildtests/tests/mcp/steps"
	proxycli "github.com/ondatra-ai/true-bdd/pkg/proxy/cli"
	"github.com/ondatra-ai/true-bdd/pkg/testkit"
	"github.com/ondatra-ai/true-bdd/pkg/testkit/bddgo"
)

//nolint:gochecknoglobals // one suite per test binary; the door owns its lifecycle.
var suite = testkit.NewSuite("mcp-service", []proxycli.Dependency{{Name: "vendor", Recording: proxycli.Recording{Placeholders: []proxycli.Placeholder{}, Unrecorded: []string{}, Unread: []string{"vendor-private/**"}, ReadOnlyWhen: map[string]string{}}}},
	func(suite *bddgo.Suite[steps.State]) { steps.Register(suite) },
	func(run *testkit.ScenarioRun) *steps.State { return &steps.State{ScenarioRun: run} },
	testkit.SuiteOptions{RepoLayer: []string{}, FixtureStep: "", RecordExclude: []string{"cache/**", "**/private/**"}})

func TestMain(m *testing.M) { os.Exit(suite.Main(m)) }

// New selects the Scenario a generated test drives.
func New(t *testing.T, scenarioID string) *bddgo.Run[steps.State] {
	t.Helper()
	return suite.New(t, scenarioID)
}

//go:build bdd

// Code generated by `true-bdd build tests`. DO NOT EDIT.
//
// Source: docs/scenarios.yaml
//
// One Go test per registry scenario, with the scenario's steps stated
// literally: what a reader sees here is what the machine runs. Done
// checks these steps against the registry before running any of them,
// so a hand edit to either side fails the test rather than quietly
// making the two documents disagree.
//
// Scenarios sharing a `path:` are written here in id order, so an
// inserted scenario lands where a reader expects it instead of at the
// end. Sequential by design — the suite's harness is shared.

package mcp_test

import (
	"testing"
)

// INT-900: MCP /mcp endpoint responds 200 to a valid initialize POST
func TestINT900(t *testing.T) {
	s := New(t, "INT-900")
	s.Given(`the MCP server is running on its configured port`)
	s.When(`the Claude User posts a valid JSON-RPC initialize request to /mcp`)
	s.Then(`the server returns HTTP 200`)
	s.Done()
}
